const frame = document.createElement("iframe");
frame.name = "epage-content";
frame.title = "ePage website content";
frame.src = "/ePage.dev/home?v=native-panels";
frame.addEventListener("load", () => {
    const path = frame.contentWindow.location.pathname;
    for (const link of ee.getControl("primarynavigation").querySelectorAll("a")) {
        if (link.pathname === path) link.setAttribute("aria-current", "page");
        else link.removeAttribute("aria-current");
    }
});
sender.appendChild(frame);

